insert into public.collections (id, name, slug, tagline, description, image, dark, category_slugs, product_slugs) values
  ('col-summer-motion', 'Summer Motion', 'summer-motion', 'Built for movement. Designed for everywhere.', 'Lightweight layers and breathable performance gear for the hottest months. Engineered to keep you moving from sunrise training to late-night city laps.', 'https://images.unsplash.com/photo-1521805103424-d8f8430e8933?auto=format&fit=crop&w=1600&q=80', false, array['running', 'training']::text[], array['volt-air-runner', 'stride-shorts', 'amplify-tee', 'aero-flex-trainer', 'feather-stride', 'velocity-elite']::text[]),
  ('col-night-run', 'Night Run', 'night-run', 'Own the streets after dark.', 'Reflective detailing, high-visibility colorways and cold-weather protection. Built for the runners who train when the city sleeps.', 'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=1600&q=80', true, array['running', 'lifestyle']::text[], array['night-run-jacket', 'volt-max-pro', 'zero-gravity', 'tempest-jacket', 'pulse-street']::text[])
insert into public.products (id, slug, name, category_id, category_name, gender, price, compare_at_price, rating, review_count, description, images, colors, sizes, sku, technology, materials, fit, care, featured, trending, is_new, collection_ids, tags) values
  ('p-volt-air-runner', 'volt-air-runner', 'Volt Air Runner', 'cat-running', 'Running', 'unisex', 165, null, 4.8, 214, 'A featherlight daily trainer built for effortless miles. The Volt Air Runner pairs a nitrogen-infused midsole with a breathable engineered mesh upper for a ride that feels fast from the first step — and stays comfortable at mile 20.', array['https://images.unsplash.com/photo-1571008887538-b36bb32f4571?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1606107557195-0e29a4b5b4aa?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Volt Orange","hex":"#ff4d00"},{"name":"Black","hex":"#0a0a0a"},{"name":"White","hex":"#f4f4f2"}]'::jsonb, '[{"size":"US 6","stock":12},{"size":"US 7","stock":18},{"size":"US 8","stock":22},{"size":"US 9","stock":14},{"size":"US 10","stock":8},{"size":"US 11","stock":6},{"size":"US 12","stock":4}]'::jsonb, 'VT-RN-1001', array['NitroFoam+ midsole', 'Engineered mesh upper', 'Carbon-reinforced plate']::text[], 'Upper: 70% recycled polyester, 30% nylon. Outsole: carbon rubber.', 'True to size. Medium width with a snug heel lock.', array['Remove insoles before washing', 'Air dry away from direct heat', 'Do not machine wash']::text[], true, true, true, array['col-summer-motion', 'col-night-run']::text[], array['running', 'daily trainer', 'cushioned', 'road running', 'breathable']::text[]),
  ('p-volt-max-pro', 'volt-max-pro', 'Volt Max Pro', 'cat-running', 'Running', 'unisex', 190, '220', 4.9, 186, 'Maximum cushioning, minimum weight. The Volt Max Pro stacks our deepest NitroFoam+ platform with a rockered geometry that propels you forward. Engineered for recovery runs, marathon blocks and every mile in between.', array['https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1560769629-975ec94e6a86?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1520975916090-3105956dac38?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Black","hex":"#0a0a0a"},{"name":"Bone","hex":"#e8e2d6"},{"name":"Volt Orange","hex":"#ff4d00"}]'::jsonb, '[{"size":"US 6","stock":0},{"size":"US 7","stock":9},{"size":"US 8","stock":16},{"size":"US 9","stock":20},{"size":"US 10","stock":11},{"size":"US 11","stock":7},{"size":"US 12","stock":3}]'::jsonb, 'VT-RN-1002', array['NitroFoam+ max stack', 'Rocker geometry', 'Waffle traction outsole']::text[], 'Upper: knit mesh with TPU support cage. Outsole: blown rubber.', 'True to size. Slightly roomier to accommodate thick running socks.', array['Spot clean with mild soap', 'Air dry', 'Avoid direct heat']::text[], true, true, false, array['col-night-run']::text[], array['running', 'max cushion', 'recovery', 'marathon', 'plush']::text[]),
  ('p-velocity-elite', 'velocity-elite', 'Velocity Elite', 'cat-running', 'Running', 'unisex', 245, null, 4.7, 98, 'Our race-day weapon. The Velocity Elite fuses a full-length carbon plate with a super-critical foam core to deliver explosive toe-off and unmatched energy return. Built to chase personal records.', array['https://images.unsplash.com/photo-1595950653106-6c9ebd614d3a?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1600185365483-26d7a4cc7519?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Signal Red","hex":"#e0342c"},{"name":"Black","hex":"#0a0a0a"},{"name":"White","hex":"#f4f4f2"}]'::jsonb, '[{"size":"US 6","stock":5},{"size":"US 7","stock":12},{"size":"US 8","stock":14},{"size":"US 9","stock":0},{"size":"US 10","stock":10},{"size":"US 11","stock":6},{"size":"US 12","stock":2}]'::jsonb, 'VT-RN-1003', array['Full-length carbon plate', 'Super-critical PEBA foam', 'AtomKnit upper']::text[], 'Upper: AtomKnit engineered yarn. Outsole: lightweight rubber pods.', 'Racing fit — snug throughout. Size up half a size if between sizes.', array['Hand wash cold', 'Air dry', 'Do not tumble dry']::text[], true, false, true, array['col-summer-motion']::text[], array['running', 'racing', 'carbon plate', 'race day', 'fast']::text[]),
  ('p-aero-flex-trainer', 'aero-flex-trainer', 'Aero Flex Trainer', 'cat-training', 'Training', 'unisex', 145, null, 4.6, 152, 'A versatile training shoe for every discipline. The Aero Flex Trainer delivers stable lateral support for lifting, flexible forefoot articulation for conditioning, and a grippy flat outsole that locks into every surface.', array['https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Charcoal","hex":"#3a3a3a"},{"name":"Electric Blue","hex":"#2563eb"},{"name":"Black","hex":"#0a0a0a"}]'::jsonb, '[{"size":"US 6","stock":10},{"size":"US 7","stock":15},{"size":"US 8","stock":19},{"size":"US 9","stock":13},{"size":"US 10","stock":9},{"size":"US 11","stock":5},{"size":"US 12","stock":7}]'::jsonb, 'VT-TR-2001', array['Stability plate', 'Flex-groove outsole', 'Reinforced heel counter']::text[], 'Upper: engineered mesh and synthetic overlays. Outsole: full-coverage rubber.', 'True to size with a locked-in midfoot.', array['Wipe with damp cloth', 'Air dry', 'Do not machine wash']::text[], true, true, false, array['col-summer-motion']::text[], array['training', 'gym', 'cross training', 'lifting', 'stable']::text[]),
  ('p-pulse-street', 'pulse-street', 'Pulse Street', 'cat-lifestyle', 'Lifestyle', 'unisex', 120, '140', 4.5, 267, 'The everyday sneaker with a pulse. The Pulse Street remixes retro court lines with a modern comfort core — a cushioned midsole, premium leather and a silhouette that goes from studio to street without missing a beat.', array['https://images.unsplash.com/photo-1606107557195-0e29a4b5b4aa?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1576678927484-cc907957088c?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1618354691373-d851c5c3a990?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"White","hex":"#f4f4f2"},{"name":"Black","hex":"#0a0a0a"},{"name":"Sulfur","hex":"#d9e021"}]'::jsonb, '[{"size":"US 6","stock":8},{"size":"US 7","stock":14},{"size":"US 8","stock":20},{"size":"US 9","stock":25},{"size":"US 10","stock":18},{"size":"US 11","stock":12},{"size":"US 12","stock":0}]'::jsonb, 'VT-LS-3001', array['CloudStep midsole', 'Premium full-grain leather', 'Padded collar']::text[], 'Upper: full-grain leather. Lining: textile. Outsole: gum rubber.', 'True to size. Wide-foot friendly.', array['Wipe with damp cloth', 'Use leather cleaner for marks', 'Air dry']::text[], false, true, false, array['col-night-run']::text[], array['lifestyle', 'sneaker', 'streetwear', 'casual', 'leather']::text[]),
  ('p-core-motion', 'core-motion', 'Core Motion Tee', 'cat-training', 'Training', 'men', 45, null, 4.4, 89, 'A four-way stretch training tee built to move with you. The Core Motion Tee uses quick-dry fabric with targeted ventilation panels to keep you cool through the heaviest sessions.', array['https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1521805103424-d8f8430e8933?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Black","hex":"#0a0a0a"},{"name":"White","hex":"#f4f4f2"},{"name":"Volt Orange","hex":"#ff4d00"}]'::jsonb, '[{"size":"XS","stock":10},{"size":"S","stock":16},{"size":"M","stock":24},{"size":"L","stock":20},{"size":"XL","stock":8},{"size":"XXL","stock":6}]'::jsonb, 'VT-TR-2002', array['Quick-dry fabric', 'Ventilation mesh panels', 'Anti-odor treatment']::text[], '88% recycled polyester, 12% spandex.', 'Athletic fit — trimmed through the body.', array['Machine wash cold', 'Do not use fabric softener', 'Tumble dry low']::text[], false, true, true, array['col-summer-motion']::text[], array['training', 'tee', 'gym', 'quick dry', 'men']::text[]),
  ('p-night-run-jacket', 'night-run-jacket', 'Night Run Jacket', 'cat-running', 'Running', 'unisex', 130, null, 4.8, 73, 'Engineered for visibility. The Night Run Jacket packs 360° reflective detailing, a water-repellent shell and packable construction into a featherlight layer designed for after-dark miles.', array['https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1518459031867-a89b944bffe4?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1560243563-062bfc001d68?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Black","hex":"#0a0a0a"},{"name":"Volt Orange","hex":"#ff4d00"},{"name":"Midnight","hex":"#16213e"}]'::jsonb, '[{"size":"XS","stock":0},{"size":"S","stock":9},{"size":"M","stock":14},{"size":"L","stock":12},{"size":"XL","stock":7},{"size":"XXL","stock":4}]'::jsonb, 'VT-RN-1004', array['360° reflective trim', 'DWR water-repellent shell', 'Packable into own pocket']::text[], 'Shell: 100% recycled ripstop nylon. Lining: breathable mesh.', 'Streamlined running fit with drop-tail hem.', array['Machine wash cold', 'Hang dry', 'Do not iron reflective panels']::text[], true, true, false, array['col-night-run']::text[], array['running', 'jacket', 'reflective', 'night run', 'water repellent']::text[]),
  ('p-stride-shorts', 'stride-shorts', 'Stride Shorts 5"', 'cat-running', 'Running', 'men', 50, null, 4.5, 121, 'Featherlight running shorts with a liner-free design, secure zip pocket and sweat-wicking fabric. The 5" inseam keeps you free for tempo days and track sessions.', array['https://images.unsplash.com/photo-1520975916090-3105956dac38?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1503341504253-dff4815485f1?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Black","hex":"#0a0a0a"},{"name":"Light Gray","hex":"#c9c9c4"},{"name":"Electric Blue","hex":"#2563eb"}]'::jsonb, '[{"size":"XS","stock":8},{"size":"S","stock":15},{"size":"M","stock":22},{"size":"L","stock":18},{"size":"XL","stock":9},{"size":"XXL","stock":0}]'::jsonb, 'VT-RN-1005', array['Sweat-wicking fabric', 'Secure zip back pocket', 'Reflective logo']::text[], '100% recycled polyester with moisture-wicking finish.', 'Standard fit with elastic waistband and drawcord.', array['Machine wash cold', 'Tumble dry low', 'Do not iron']::text[], false, false, false, array['col-summer-motion']::text[], array['running', 'shorts', 'summer', 'track', 'men']::text[]),
  ('p-amplify-tee', 'amplify-tee', 'Amplify Run Tee', 'cat-running', 'Running', 'women', 40, null, 4.6, 84, 'A second-skin running tee with a soft-touch recycled knit, bonded seams and a drop-tail hem. The Amplify Tee disappears on your body so you can focus on the road ahead.', array['https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1543076447-215ad9ba6923?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1608231387042-66d1773070a5?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Bone","hex":"#e8e2d6"},{"name":"Coral","hex":"#ff6b57"},{"name":"Black","hex":"#0a0a0a"}]'::jsonb, '[{"size":"XS","stock":12},{"size":"S","stock":18},{"size":"M","stock":20},{"size":"L","stock":11},{"size":"XL","stock":5},{"size":"XXL","stock":3}]'::jsonb, 'VT-RN-1006', array['Bonded seams', 'Soft-touch recycled knit', 'Moisture-wicking finish']::text[], '78% recycled polyester, 22% spandex.', 'Slim, second-skin fit.', array['Machine wash cold', 'Air dry', 'Do not iron logos']::text[], false, true, true, array['col-summer-motion']::text[], array['running', 'tee', 'women', 'second skin', 'breathable']::text[]),
  ('p-court-surge', 'court-surge', 'Court Surge', 'cat-basketball', 'Basketball', 'unisex', 175, '195', 4.7, 143, 'Built to explode. The Court Surge wraps your foot in a lockdown fit system with responsive heel cushioning and a herringbone outsole that grips the hardwood through every cut, jump and landing.', array['https://images.unsplash.com/photo-1546519638-68e109498ffc?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1591047139829-d91aecb6caea?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1504450758481-7338eba7524a?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Black","hex":"#0a0a0a"},{"name":"Signal Red","hex":"#e0342c"},{"name":"White","hex":"#f4f4f2"}]'::jsonb, '[{"size":"US 6","stock":6},{"size":"US 7","stock":11},{"size":"US 8","stock":17},{"size":"US 9","stock":15},{"size":"US 10","stock":9},{"size":"US 11","stock":0},{"size":"US 12","stock":5}]'::jsonb, 'VT-BB-4001', array['Lockdown fit system', 'Responsive heel foam', 'Herringbone traction']::text[], 'Upper: knit with fused overlays. Outsole: high-abrasion rubber.', 'True to size with a snug, secure fit.', array['Wipe with damp cloth', 'Air dry', 'Store at room temperature']::text[], true, true, false, array[]::text[], array['basketball', 'court', 'hoops', 'performance', 'grip']::text[]),
  ('p-zero-gravity', 'zero-gravity', 'Zero Gravity Runner', 'cat-running', 'Running', 'unisex', 155, null, 4.6, 67, 'Float over any surface. The Zero Gravity Runner pairs a dual-density midsole with a grippy trail-ready outsole, making it equally at home on pavement, gravel and groomed trails.', array['https://images.unsplash.com/photo-1560769629-975ec94e6a86?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1520975916090-3105956dac38?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1595950653106-6c9ebd614d3a?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Forest Green","hex":"#1f5c3d"},{"name":"Black","hex":"#0a0a0a"},{"name":"Volt Orange","hex":"#ff4d00"}]'::jsonb, '[{"size":"US 6","stock":4},{"size":"US 7","stock":10},{"size":"US 8","stock":13},{"size":"US 9","stock":16},{"size":"US 10","stock":8},{"size":"US 11","stock":6},{"size":"US 12","stock":2}]'::jsonb, 'VT-RN-1007', array['Dual-density midsole', 'Trail-grip outsole', 'Rock shield']::text[], 'Upper: ripstop mesh. Outsole: multi-directional lugs.', 'True to size. Roomy toe box.', array['Brush off dirt after runs', 'Air dry', 'Do not machine wash']::text[], false, false, true, array['col-night-run']::text[], array['running', 'trail', 'hybrid', 'gravel', 'cushioned']::text[]),
  ('p-tempest-jacket', 'tempest-jacket', 'Tempest Shell Jacket', 'cat-running', 'Running', 'women', 140, null, 4.7, 42, 'Storm-proof, motion-ready. The Tempest Shell uses a fully seam-sealed waterproof membrane with articulated sleeves and a helmet-compatible hood — protection that never slows you down.', array['https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1558611848-73f7eb4001a1?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Midnight","hex":"#16213e"},{"name":"Coral","hex":"#ff6b57"},{"name":"Black","hex":"#0a0a0a"}]'::jsonb, '[{"size":"XS","stock":7},{"size":"S","stock":12},{"size":"M","stock":15},{"size":"L","stock":9},{"size":"XL","stock":4},{"size":"XXL","stock":0}]'::jsonb, 'VT-RN-1008', array['Seam-sealed waterproof membrane', 'Articulated sleeves', 'Adjustable hood']::text[], 'Shell: 100% recycled polyester with waterproof membrane.', 'Athletic fit with room for light layers.', array['Machine wash cold', 'Hang dry', 'Reapply DWR as needed']::text[], false, false, true, array['col-night-run']::text[], array['running', 'jacket', 'waterproof', 'rain', 'women']::text[]),
  ('p-kinetic-legging', 'kinetic-legging', 'Kinetic High-Rise Legging', 'cat-training', 'Training', 'women', 78, '90', 4.8, 158, 'Sculpting support with total freedom of movement. The Kinetic Legging features a high-rise waistband, squat-proof fabric and a hidden phone pocket — engineered to stay in place through every rep.', array['https://images.unsplash.com/photo-1518611012118-696072aa579a?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1516726817505-f5ed825624d8?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Black","hex":"#0a0a0a"},{"name":"Forest Green","hex":"#1f5c3d"},{"name":"Charcoal","hex":"#3a3a3a"}]'::jsonb, '[{"size":"XS","stock":14},{"size":"S","stock":20},{"size":"M","stock":18},{"size":"L","stock":12},{"size":"XL","stock":6},{"size":"XXL","stock":4}]'::jsonb, 'VT-TR-2003', array['Squat-proof compression', 'Hidden phone pocket', 'Flatlock seams']::text[], '75% recycled nylon, 25% elastane.', 'High-rise, true to size. Compression fit.', array['Machine wash cold', 'Do not use fabric softener', 'Hang dry']::text[], false, true, false, array['col-summer-motion']::text[], array['training', 'legging', 'women', 'gym', 'compression']::text[]),
  ('p-rebound-hoodie', 'rebound-hoodie', 'Rebound Hoodie', 'cat-lifestyle', 'Lifestyle', 'unisex', 85, null, 4.6, 95, 'A heavyweight streetwear essential. The Rebound Hoodie is cut from 450gsm loopback fleece with a dropped shoulder, ribbed side panels and a kangaroo pocket built for the everyday.', array['https://images.unsplash.com/photo-1517438476312-10d79c077509?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1574680096145-d05b474e2155?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Black","hex":"#0a0a0a"},{"name":"Bone","hex":"#e8e2d6"},{"name":"Volt Orange","hex":"#ff4d00"}]'::jsonb, '[{"size":"XS","stock":9},{"size":"S","stock":15},{"size":"M","stock":21},{"size":"L","stock":17},{"size":"XL","stock":10},{"size":"XXL","stock":5}]'::jsonb, 'VT-LS-3002', array['450gsm loopback fleece', 'Ribbed side panels', 'Dropped shoulder']::text[], '80% organic cotton, 20% recycled polyester.', 'Relaxed, oversized fit.', array['Machine wash cold', 'Tumble dry low', 'Wash inside out']::text[], false, true, false, array[]::text[], array['lifestyle', 'hoodie', 'streetwear', 'fleece', 'unisex']::text[]),
  ('p-feather-stride', 'feather-stride', 'Feather Stride', 'cat-running', 'Running', 'women', 160, null, 4.8, 76, 'Weightless cushioning engineered for the female foot. The Feather Stride uses a gender-tuned foam distribution and a narrower heel geometry for a smooth, responsive ride on every run.', array['https://images.unsplash.com/photo-1600185365483-26d7a4cc7519?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1571008887538-b36bb32f4571?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1520975916090-3105956dac38?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"White","hex":"#f4f4f2"},{"name":"Coral","hex":"#ff6b57"},{"name":"Bone","hex":"#e8e2d6"}]'::jsonb, '[{"size":"US 6","stock":16},{"size":"US 7","stock":20},{"size":"US 8","stock":12},{"size":"US 9","stock":9},{"size":"US 10","stock":4},{"size":"US 11","stock":3},{"size":"US 12","stock":1}]'::jsonb, 'VT-RN-1009', array['Gender-tuned foam', 'Narrower heel geometry', 'Breathable mesh upper']::text[], 'Upper: recycled mesh. Outsole: carbon rubber.', 'True to size. Narrower through the heel.', array['Remove insoles before washing', 'Air dry', 'Do not machine wash']::text[], true, true, true, array['col-summer-motion']::text[], array['running', 'women', 'daily trainer', 'lightweight', 'cushioned']::text[]),
  ('p-flex-knit-pant', 'flex-knit-pant', 'Flex Knit Training Pant', 'cat-training', 'Training', 'men', 70, null, 4.4, 58, 'Warm-up or cool-down, the Flex Knit Pant moves with you. A brushed knit interior, tapered leg and zip ankle cuffs make layering effortless from the gym to the street.', array['https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1571902943202-507ec2618e8f?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Black","hex":"#0a0a0a"},{"name":"Graphite","hex":"#4a4a4a"},{"name":"Midnight","hex":"#16213e"}]'::jsonb, '[{"size":"XS","stock":6},{"size":"S","stock":13},{"size":"M","stock":19},{"size":"L","stock":16},{"size":"XL","stock":8},{"size":"XXL","stock":3}]'::jsonb, 'VT-TR-2004', array['Brushed knit interior', 'Tapered leg', 'Zip ankle cuffs']::text[], '70% recycled polyester, 30% cotton.', 'Regular fit, tapered through the leg.', array['Machine wash cold', 'Tumble dry low', 'Do not iron']::text[], false, false, false, array[]::text[], array['training', 'pants', 'gym', 'jogger', 'men']::text[]),
  ('p-metro-classic', 'metro-classic', 'Metro Classic Low', 'cat-lifestyle', 'Lifestyle', 'unisex', 105, '120', 4.3, 203, 'A timeless low-top silhouette with a modern comfort core. The Metro Classic Low is finished in premium suede with a vulcanized sole — the clean canvas for every rotation.', array['https://images.unsplash.com/photo-1591047139829-d91aecb6caea?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1521805103424-d8f8430e8933?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"White","hex":"#f4f4f2"},{"name":"Black","hex":"#0a0a0a"},{"name":"Light Gray","hex":"#c9c9c4"}]'::jsonb, '[{"size":"US 6","stock":12},{"size":"US 7","stock":18},{"size":"US 8","stock":22},{"size":"US 9","stock":24},{"size":"US 10","stock":15},{"size":"US 11","stock":9},{"size":"US 12","stock":6}]'::jsonb, 'VT-LS-3003', array['CloudStep comfort core', 'Vulcanized sole', 'Premium suede upper']::text[], 'Upper: premium suede. Lining: textile. Outsole: vulcanized rubber.', 'True to size. Medium width.', array['Use suede brush', 'Protect with suede spray', 'Air dry']::text[], false, false, false, array[]::text[], array['lifestyle', 'sneaker', 'suede', 'classic', 'low top']::text[]),
  ('p-volt-air-runner-kids', 'volt-air-runner-kids', 'Volt Air Runner Kids', 'cat-running', 'Running', 'kids', 95, null, 4.7, 34, 'All the speed, sized for the next generation. The Volt Air Runner Kids brings our signature lightweight cushioning to growing feet with a roomier toe box and easy hook-and-loop options on smaller sizes.', array['https://images.unsplash.com/photo-1571008887538-b36bb32f4571?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1503341504253-dff4815485f1?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?auto=format&fit=crop&w=1200&q=80']::text[], '[{"name":"Volt Orange","hex":"#ff4d00"},{"name":"Electric Blue","hex":"#2563eb"},{"name":"Black","hex":"#0a0a0a"}]'::jsonb, '[{"size":"S 10C","stock":10},{"size":"S 11C","stock":14},{"size":"S 12C","stock":12},{"size":"S 1Y","stock":9},{"size":"S 2Y","stock":7},{"size":"S 3Y","stock":4}]'::jsonb, 'VT-RN-1010', array['Kid-tuned cushioning', 'Roomier toe box', 'Easy closure options']::text[], 'Upper: recycled mesh. Outsole: durable rubber.', 'Roomier fit for growing feet.', array['Wipe with damp cloth', 'Air dry', 'Do not machine wash']::text[], false, false, true, array[]::text[], array['running', 'kids', 'school', 'play', 'lightweight']::text[])
